                    "customer_id": customer.customer_id,
                    "name": customer.name,
                    "lifetime_value_cents": lifetime_value_cents,
                })

        customers_list.sort(key=lambda c: (-c["lifetime_value_cents"], c["customer_id"]))
        return Response(200, {"customers": customers_list[:limit]})

